arguments.file_text:
.catalog-page {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    min-height: 100vh;
}

/* Sidebar Filters */
.catalog-filters {
    width: 25%;
    min-width: 220px;
    padding: 1rem;
    border-right: 1px solid #e0e0e0;
}

.catalog-filters h3 {
    margin-top: 0;
    margin-bottom: 1rem;
}

.filter-section {
    margin-bottom: 1.5rem;
}

.filter-section h4 {
    margin-bottom: 0.5rem;
    font-size: 0.9rem;
    text-transform: uppercase;
    color: #555;
}

.filter-checkbox {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.4rem;
    cursor: pointer;
}

.filter-section label:not(.filter-checkbox) {
    display: block;
    margin-bottom: 0.5rem;
    font-size: 0.9rem;
}

.filter-section input[type="number"] {
    width: 100%;
    padding: 0.4rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    margin-top: 0.2rem;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.btn-apply,
.btn-clear {
    padding: 0.6rem 1rem;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-apply {
    background: #0d6efd;
    color: white;
}

.btn-apply:hover {
    background: #0b5ed7;
}

.btn-clear {
    background: #6c757d;
    color: white;
}

.btn-clear:hover {
    background: #5c636a;
}

/* Main Content */
.catalog-main {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

/* Toolbar */
.catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border-radius: 4px;
}

.toolbar-sort {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.toolbar-sort select {
    padding: 0.4rem 0.6rem;
    border: 1px solid #ccc;
    border-radius: 4px;
}

.toolbar-info {
    color: #666;
    font-size: 0.9rem;
}

/* Product Grid */
.product-grid {
